  const WORK_SPOTS = [{"name": "La Caféothèque", "desc": "Paris's first specialty roaster, a block off the Seine, with the sacks and the drum in the next room", "maps": "https://www.google.com/maps/search/?api=1&query=La+Caf%C3%A9oth%C3%A8que+Paris"}, {"name": "Belleville Brûlerie", "desc": "The 2013 micro-roastery whose beans now fill the hoppers of half the city's good cafés", "maps": "https://www.google.com/maps/search/?api=1&query=Belleville+Br%C3%BBlerie+Paris"}, {"name": "Télescope", "desc": "A tiny white room behind the Palais-Royal that showed the Right Bank what an espresso could taste like", "maps": "https://www.google.com/maps/search/?api=1&query=T%C3%A9lescope+rue+Villedo+Paris"}, {"name": "Salle Ovale, BnF Richelieu", "desc": "Under a glass dome, 160 seats and 20,000 open books, free to anyone who walks in", "maps": "https://www.google.com/maps/search/?api=1&query=Salle+Ovale+BnF+Richelieu+Paris"}, {"name": "Bibliothèque Mazarine", "desc": "France's oldest public library, still a working reading room under Mazarin's carved bookcases", "maps": "https://www.google.com/maps/search/?api=1&query=Biblioth%C3%A8que+Mazarine+Paris"}, {"name": "Anticafé", "desc": "You pay for the hours, not the cup: coffee, snacks and Wi-Fi included, and a seat you are meant to keep", "maps": "https://www.google.com/maps/search/?api=1&query=Anticaf%C3%A9+Louvre+Paris"}, {"name": "Café de Flore", "desc": "Red banquettes and mirrors from the 1880s, and the upstairs room where Baldwin wrote over cognac", "maps": "https://www.google.com/maps/search/?api=1&query=Caf%C3%A9+de+Flore+Paris"}, {"name": "Les Deux Magots", "desc": "Two carved Chinese figures on a pillar, a terrace facing the oldest church in Paris, jazz on Thursdays", "maps": "https://www.google.com/maps/search/?api=1&query=Les+Deux+Magots+Paris"}, {"name": "Le Sélect", "desc": "The 1923 Montparnasse café that still serves past midnight, marble tables and all", "maps": "https://www.google.com/maps/search/?api=1&query=Le+Select+Montparnasse+Paris"}, {"name": "Le Pavillon des Canaux", "desc": "A canal keeper's house turned café: work in a former bedroom, or in the bathtub, with the water outside", "maps": "https://www.google.com/maps/search/?api=1&query=Le+Pavillon+des+Canaux+Paris"}, {"name": "Ten Belles", "desc": "A 2012 counter by the Canal Saint-Martin, where the queue spills onto the pavement for a cortado", "maps": "https://www.google.com/maps/search/?api=1&query=Ten+Belles+Paris"}, {"name": "Café Craft", "desc": "Built from the start for people who came to work: long tables, a socket at every seat, Wi-Fi that holds", "maps": "https://www.google.com/maps/search/?api=1&query=Caf%C3%A9+Craft+Paris"}];
