  const PHOTOS = [{"src": "/terroir/Paris/img/ph-1-cafe-de-flore-paris.jpg", "caption": "A Left Bank café-comptoir — the city's public living room, not a staged terrace.", "credit": "Celette · CC BY-SA 4.0 · Wikimedia Commons"}, {"src": "/terroir/Paris/img/ph-2-louvre-pyramid-cour-napo.jpg", "caption": "The Cour Napoléon — Pei's pyramid dropped into a 16th-century courtyard.", "credit": "Benh LIEU SONG · CC BY 2.5 · Wikimedia Commons"}, {"src": "/terroir/Paris/img/ph-4-marche-d-aligre-paris.jpg", "caption": "The market from the seller's side, where the chefs do their morning rounds.", "credit": "Mbzt · CC BY 3.0 · Wikimedia Commons"}];
  const GEMS = [{"id": "gem-restaurant", "pattern": "La Grande Taverne de Londres", "tag": "Paris gem · born here", "name": "The restaurant itself", "story": "The word came first: 'restaurants' were restorative bouillons sold to the delicate in the 1760s. Folklore credits a soup-seller called Boulanger in 1765; the historian Rebecca Spang traced that tale to a book of 1782 and found no record he existed, crediting instead Mathurin Roze de Chantoiseau, who opened a room around 1766 or 1767.", "where": "The Palais-Royal arcades, where the first grand restaurants stood."}, {"id": "gem-croque", "pattern": "croque-monsieur", "tag": "Paris gem · born here", "name": "The crunch-mister", "story": "The grilled ham-and-cheese is usually dated to about 1910 on the boulevard des Capucines, a café's quick bite for theatregoers; an earlier printed mention turns up in an 1891 review, and Proust names it in 1919. The name, 'crunch-mister', is counter humour, and its story is folk etymology.", "where": "The old cafés of Saint-Germain still make it seriously."}, {"id": "gem-paris-brest", "pattern": "Paris-Brest", "tag": "Paris gem · born nearby", "name": "A cake shaped like a wheel", "story": "In 1910 the journalist Pierre Giffard, who had created the Paris–Brest–Paris cycle race in 1891, asked the pâtissier Louis Durand of Maisons-Laffitte, on the route, for a cake to mark it. Durand piped a ring of choux like a bicycle wheel, filled it with praline cream and scattered it with almonds. His family still bakes it there.", "where": "Pâtisserie Durand, avenue de Longueil, Maisons-Laffitte."}, {"id": "gem-opera", "pattern": "Dalloyau", "tag": "Paris gem · born here", "name": "A cake for the opera house", "story": "Generally credited to 1955 at Dalloyau, where Cyriaque Gavillon layered almond sponge soaked in coffee syrup with coffee buttercream and ganache so that one bite carried everything; his wife Andrée named it for the Palais Garnier. Lenôtre (1960) and the chef Louis Clichy are rival claimants; Le Monde credited Gavillon in 1988.", "where": "Dalloyau, 101 rue du Faubourg Saint-Honoré, the house of origin."}, {"id": "gem-tartare", "pattern": "tartare", "tag": "Paris gem · a myth corrected", "name": "No saddle, no Tatars", "story": "The tale of horsemen tenderising raw meat under their saddles goes back to Joinville in the thirteenth century, and the saddle meat was for the horse's sores. The dish is prosaic and Parisian: steak à l'américaine in the early 1900s, and Escoffier's 1922 Guide Culinaire defines 'à la tartare' as that steak without the egg yolk but with tartare sauce.", "where": "A bistro that cuts it by hand, to order."}, {"id": "gem-jambon-beurre", "pattern": "jambon-beurre", "tag": "Paris gem · born here", "name": "Fuel for the porters", "story": "A split baguette, good butter, boiled ham, nothing else: it took shape in the nineteenth century as cheap fuel for the porters of Les Halles, with the baguette becoming its bread in the 1920s. It is still the country's benchmark sandwich, even after hamburgers outsold it in 2017 by the Gira Conseil count.", "where": "A good boulangerie, or the counter near the Opéra in the tables."}];
  const TABLES = {"grande": {"title": "Les Grandes Tables", "desc": "The tables you clear an evening for — and book before you fly: three three-star houses, the new haute of the counter and the fire, and the grand rooms with a date over the door.", "sections": [{"label": "La Crème — the three-star houses", "desc": "The three-star rooms: the garden on a plate, the sauce house on the Seine, and a Japanese-born chef's French kitchen.", "ids": ["v-l-arpege", "v-plenitude-cheval-blanc-paris", "v-kei"]}, {"label": "The new haute — the produce and the fire", "desc": "A counter where the produce is the menu, a plant-forward kitchen in the Marais, and binchotan with handmade pasta.", "ids": ["v-table-by-bruno-verjus", "v-datil", "v-le-rigmarole"]}, {"label": "The grand rooms — dated", "desc": "1784, 1901, and the Monnaie: the oldest dining room in the city, a station buffet under painted ceilings, a chef's house in the mint.", "ids": ["v-le-grand-vefour", "v-guy-savoy", "v-le-train-bleu"]}]}, "petite": {"title": "Les Petites Tables", "desc": "Where this guide actually lives: the neo-bistros of the 11th, the bistro canon, the wine bistros, the brasseries and the bouillons, and two rooms you walk into by day.", "sections": [{"label": "The neo-bistro line — the 11th", "desc": "The 11th made the neo-bistro: Septime, a sister-run room on rue Saint-Maur, and a circus tile room by the Cirque d'Hiver.", "ids": ["v-septime", "v-le-servan", "v-clown-bar"]}, {"label": "The bistro canon", "desc": "Steak au poivre on rue Paul Bert, the Basque canteen by the Invalides, and the old Sentier bistro that never changed.", "ids": ["v-bistrot-paul-bert", "v-chez-l-ami-jean", "v-chez-georges"]}, {"label": "The wine bistros — the cellar first", "desc": "The cellar comes first: Raquel Carena's blackboard in Belleville, a wine bistro in the Marais, and a cellar of thousands in the 11th.", "ids": ["v-le-baratin", "v-parcelles", "v-vantre"]}, {"label": "The brasseries — dated", "desc": "1880, 1864, 1927: the Left Bank's Alsatian room, the Bastille's glass dome, and Montparnasse's Art Deco hall.", "ids": ["v-brasserie-lipp", "v-bofinger", "v-la-coupole"]}, {"label": "The bouillons and the crémerie — cheap since the 1800s", "desc": "The workers' canteens: Chartier of 1896, the crémerie of 1845, and the revival on the boulevard de Clichy.", "ids": ["v-bouillon-chartier", "v-polidor", "v-bouillon-pigalle"]}, {"label": "Walk in by day — the seafood bar and the day kitchen", "desc": "No bookings for the raw bar on rue de Charonne, and a weekday day kitchen two streets away.", "ids": ["v-clamato", "v-mokonuts"]}]}, "street": {"title": "La Rue — The Street", "desc": "At the window and at the counter: falafel, the sandwich, the ham, the galette and the steak.", "sections": [{"label": "At the window — falafel, the sandwich, the ham", "desc": "The rue des Rosiers falafel, the griddled sandwich of the rue Charlot, and the jambon-beurre near the Opéra.", "ids": ["v-l-as-du-fallafel", "v-chez-alain-miam-miam", "v-le-petit-vendome"]}, {"label": "One dish, one room — the galette and the steak", "desc": "The galette of Brittany done properly twice, and the steak-frites room with one menu.", "ids": ["v-breizh-cafe", "v-la-creperie-de-josselin", "v-le-relais-de-l-entrecote"]}]}};
  const CATEGORIES = [{"key": "creme", "label": "La Crème — the three-star houses", "lead": "The three-star rooms: the garden on a plate, the sauce house on the Seine, and a Japanese-born chef's French kitchen.", "story": {"title": "Three stars, three answers", "story": "Paris went into the 2026 MICHELIN guide with nine three-star tables, and L'Ambroisie, the oldest of them, came out with two. Three of the nine are in this lane, each answering the question of luxury differently. L'Arpège, Alain Passard's room on the site of his old boss's L'Archestrate, struck every animal product but its own honey from the menu in July 2025 and kept its stars. Plénitude, inside Cheval Blanc on the Seine, went from nothing to three in March 2022 on the strength of Arnaud Donckele's numbered sauces. Kei, near the Louvre, made Kei Kobayashi in 2020 the first Japanese-born chef to hold three stars in France.", "where": "L'Arpège on rue de Varenne; Plénitude on Quai du Louvre; Kei on rue Coq-Héron"}}, {"key": "produce", "label": "The new haute — the produce and the fire", "lead": "A counter where the produce is the menu, a plant-forward kitchen in the Marais, and binchotan with handmade pasta.", "story": {"title": "The day's market, cooked", "story": "These kitchens are written from what came in that morning rather than from a fixed repertoire. Table, opened in 2013 by Bruno Verjus, a former critic who started cooking in his fifties, serves one daily menu at a counter by the Marché d'Aligre; it reached No. 3 in the world in 2024 and will serve for the last time on 22 December 2026. Datil, Manon Fleury's room in the 3rd since 2023, opens on a broth of peelings and won a MICHELIN Green Star in March 2026. Le Rigmarole, in the 11th, cooks over Japanese binchotan and rolls Italian pasta by hand at the same walnut counter.", "where": "Table by Bruno Verjus by the Marché d'Aligre; Datil on rue des Gravilliers; Le Rigmarole on rue du Grand Prieuré"}}, {"key": "grand", "label": "The grand rooms — dated", "lead": "1784, 1901, and the Monnaie: the oldest dining room in the city, a station buffet under painted ceilings, a chef's house in the mint.", "story": {"title": "Rooms older than menus", "story": "In these three the room came first and the cooking has changed hands around it. Le Grand Véfour has traded under the Palais-Royal arcades since 1784; Guy Martin left at the end of 2025, and on 12 May 2026 Paris Society reopened it with Bruno Doucet carving lamb at the table and a 150-seat garden terrace. Guy Savoy moved in 2015 into the first floor of the Monnaie de Paris, the old royal mint; MICHELIN took one star in 2023, while La Liste still ranks it first. Le Train Bleu, above Gare de Lyon since 1901, has had its painted walls listed as a monument since 1972.", "where": "Le Grand Véfour on rue de Beaujolais; Guy Savoy on Quai de Conti; Le Train Bleu on Place Louis-Armand"}}, {"key": "neo", "label": "The neo-bistro line — the 11th", "lead": "The 11th made the neo-bistro: Septime, a sister-run room on rue Saint-Maur, and a circus tile room by the Cirque d'Hiver.", "story": {"title": "The 11th's small plates", "story": "The neo-bistro, a short menu of ambitious cooking in a plain room at bistro prices, took root in the 11th in the 2010s. Septime opened on rue de Charonne in 2011, won a star in 2014 and became the template; its founding chef Bertrand Grébaut died in July 2026, aged 44, and the room cooks on. Le Servan, opened in 2014 by Tatiana and Katia Levha in an old bar on rue Saint-Maur, was Le Fooding's best bistro of 2015 and serves blood-sausage wontons. Clown Bar, the Cirque d'Hiver's 1902 bar, was taken over in 2014 by the Saturne team and kept its listed clown frieze.", "where": "Septime on rue de Charonne; Le Servan on rue Saint-Maur; Clown Bar on rue Amelot"}}, {"key": "bistro", "label": "The bistro canon", "lead": "Steak au poivre on rue Paul Bert, the Basque canteen by the Invalides, and the old Sentier bistro that never changed.", "story": {"title": "Bistros that kept the script", "story": "The classic Paris bistro runs on a short list: terrine, steak, liver, rice pudding, a phone you have to call. Bistrot Paul Bert, opened in 1997 by Bertrand Auboyneau, a former finance man, built its name on steak au poivre and growers' wine and still takes bookings by phone only. Chez L'Ami Jean, Stéphane Jégo's Basque canteen near the Invalides since 2002, is known for a single shared bowl of riz au lait and autumn game. Chez Georges, on rue du Mail since 1964, still hands out a menu written by hand and closes every weekend and through August.", "where": "Bistrot Paul Bert on rue Paul Bert; Chez L'Ami Jean on rue Malar; Chez Georges on rue du Mail"}}, {"key": "wine", "label": "The wine bistros — the cellar first", "lead": "The cellar comes first: Raquel Carena's blackboard in Belleville, a wine bistro in the Marais, and a cellar of thousands in the 11th.", "story": {"title": "The cellar comes first", "story": "In these rooms the wine list was there before the menu and the person who runs it owns the place. At Le Baratin in Belleville, Philippe Pinoteau has poured natural wine since 1992 beside Raquel Carena, who has cooked there since 1987. At Parcelles, in a 1936 café on rue Chapon, sommelier Bastien Fidelin also runs the wine shop across the street, and Gault&Millau's 2026 review scores the kitchen 13/20. At Vantre on rue de la Fontaine-au-Roi, Marco Pelletier, formerly of Le Bristol and Taillevent, won a Wine Spectator Grand Award in 2019 for a room of about 30 seats, open weekdays only.", "where": "Le Baratin on rue Jouye-Rouve; Parcelles on rue Chapon; Vantre on rue de la Fontaine-au-Roi"}}, {"key": "brasserie", "label": "The brasseries — dated", "lead": "1880, 1864, 1927: the Left Bank's Alsatian room, the Bastille's glass dome, and Montparnasse's Art Deco hall.", "story": {"title": "Alsace came to Paris", "story": "The Paris brasserie began as a beer hall, often Alsatian, and these three still serve choucroute under listed ceilings. Bofinger near the Bastille dates from 1864 and its glass-domed room was open for Heritage Days tours in 2026. Brasserie Lipp opened on boulevard Saint-Germain in 1880 and hands out its own literary award, the Prix Cazes, every November; Gault&Millau's 2026 review finds its carte barely changed since the 1950s. La Coupole arrived in Montparnasse in 1927 with pillars painted by 27 artists and a lamb curry that has never left the menu. Groupe Bertrand now owns all three.", "where": "Bofinger on rue de la Bastille; Brasserie Lipp on boulevard Saint-Germain; La Coupole on boulevard du Montparnasse"}}, {"key": "bouillon", "label": "The bouillons and the crémerie — cheap since the 1800s", "lead": "The workers' canteens: Chartier of 1896, the crémerie of 1845, and the revival on the boulevard de Clichy.", "story": {"title": "Cheap since the 1800s", "story": "Bouillons were invented in the 1850s by Pierre-Louis Duval, a butcher, to feed the workers of Les Halles broth and boiled beef for very little money. Bouillon Chartier on rue du Faubourg Montmartre has done it since 1896, in a hall listed in 1989, with no bookings and waiters who write the bill on the tablecloth. Bouillon Pigalle revived the format in 2017 with 300 seats; Gault&Millau's 2026 review prices its bourguignon at EUR 12.20. Polidor started as a crémerie in 1845 and has a different plat du jour for every weekday, the semainier.", "where": "Bouillon Chartier on rue du Faubourg Montmartre; Bouillon Pigalle on boulevard de Clichy; Polidor on rue Monsieur-le-Prince"}}, {"key": "day", "label": "Walk in by day — the seafood bar and the day kitchen", "lead": "No bookings for the raw bar on rue de Charonne, and a weekday day kitchen two streets away.", "story": {"title": "No booking, or book weeks out", "story": "Two rooms in the 11th that run on daytime hours and work in opposite ways. Clamato on rue de Charonne, opened in 2013 by the Septime team, has never taken a reservation: you queue, and the menu depends on what the boats from Saint-Jean-de-Luz, Concarneau and the Île d'Yeu sent that morning. MICHELIN gives it a Bib Gourmand. Mokonuts on rue Saint-Bernard, near the Aligre market, has about twenty seats, serves weekdays only and closes in the afternoon; tables go weeks ahead, and Paris by Mouth's 2026 revisit kept it on its favourites list. If you cannot get a table, buy the cookies.", "where": "Clamato on rue de Charonne; Mokonuts on rue Saint-Bernard"}}, {"key": "window", "label": "At the window — falafel, the sandwich, the ham", "lead": "The rue des Rosiers falafel, the griddled sandwich of the rue Charlot, and the jambon-beurre near the Opéra.", "story": {"title": "Lunch eaten standing up", "story": "Paris street lunch is eaten standing up, and the queue is part of the meal. L'As du Fallafel has served pita from its green window on rue des Rosiers since 1979; it is kosher, so it shuts at 17:00 on Friday and stays closed Saturday. Chez Alain Miam Miam made its name at a stall in the Marché des Enfants Rouges, which fire destroyed in October 2026; its own counter on rue Charlot builds toasted sandwiches by hand, but check it is open. Le Petit Vendôme on rue des Capucines sells ham and butter on a baguette, ranked the world's best sandwich by Time Out in 2025.", "where": "L'As du Fallafel on rue des Rosiers; Chez Alain Miam Miam on rue Charlot; Le Petit Vendôme on rue des Capucines"}}, {"key": "onedish", "label": "One dish, one room — the galette and the steak", "lead": "The galette of Brittany done properly twice, and the steak-frites room with one menu.", "story": {"title": "One dish, done the same way", "story": "Each of these rooms serves one main dish and has kept it the same for decades. Bretons came to Paris through Gare Montparnasse, and La Crêperie de Josselin on rue du Montparnasse makes buckwheat galettes on a billig and pours cider into bowls. Breizh Café in the Marais, founded by Bertrand Larcher after he opened in Tokyo, makes the same galette with Bordier butter and IGP buckwheat. Le Relais de l'Entrecôte on rue Saint-Benoît has offered one menu since 1959: walnut salad, then steak-frites in a sauce whose recipe has never been published, with the second helping included.", "where": "La Crêperie de Josselin on rue du Montparnasse; Breizh Café on rue Vieille du Temple; Le Relais de l'Entrecôte on rue Saint-Benoît"}}];
